components.css:
.ds-btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background: #f1efe8;
  color: #0d0f13;
  font-family: 'Bricolage Grotesque', sans-serif;
  font-weight: 700;
  font-size: 14px;
  letter-spacing: 0.02em;
  border: none;
  border-radius: 4px;
  padding: 12px 20px;
  cursor: pointer;
  transition: background-color 0.15s, color 0.15s;
}
.ds-btn-primary:hover {
  background: #ff5c4d;
  color: #0d0f13;
}
.ds-btn-primary:focus-visible {
  outline: 2px solid #ff5c4d;
  outline-offset: 2px;
}
.ds-btn-primary:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}
.ds-btn-primary:disabled:hover {
  background: #f1efe8;
  color: #0d0f13;
}

.ds-btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: transparent;
  color: #8f939e;
  font-family: 'IBM Plex Mono', monospace;
  font-weight: 400;
  font-size: 11px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  border: 1px solid rgba(241,239,232,0.09);
  border-radius: 4px;
  padding: 8px 16px;
  cursor: pointer;
  transition: color 0.15s, border-color 0.15s;
}
.ds-btn-ghost:hover {
  color: #f1efe8;
  border-color: rgba(241,239,232,0.24);
}
.ds-btn-ghost:focus-visible {
  outline: 2px solid #ff5c4d;
  outline-offset: 2px;
}

.ds-cta-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: #ff5c4d;
  color: #0d0f13;
  font-family: 'Bricolage Grotesque', sans-serif;
  font-weight: 700;
  font-size: 14px;
  letter-spacing: 0.025em;
  border: none;
  border-radius: 9999px;
  padding: 10px 20px;
  cursor: pointer;
  transition: box-shadow 0.2s, transform 0.2s;
}
.ds-cta-pill:hover {
  box-shadow: 0 24px 64px rgba(0,0,0,0.55);
  transform: scale(1.05);
}
.ds-cta-pill:focus-visible {
  outline: 2px solid #ff5c4d;
  outline-offset: 2px;
}

.ds-display-num {
  font-family: 'Bricolage Grotesque', sans-serif;
  font-weight: 800;
  font-size: clamp(3rem, 7vw, 5.5rem);
  line-height: 1;
  letter-spacing: -0.04em;
  font-variation-settings: 'wdth' 80;
  font-variant-numeric: tabular-nums;
}

.ds-challenge-card {
  display: flex;
  flex-direction: column;
  background: #14171d;
  border: 1px solid rgba(241,239,232,0.09);
  border-radius: 8px;
  padding: 24px;
  text-align: left;
  transition: transform 0.2s, border-color 0.2s, box-shadow 0.2s;
}
.ds-challenge-card:hover {
  transform: translateY(-2px);
  border-color: rgba(241,239,232,0.24);
  box-shadow: 0 2px 12px rgba(0,0,0,0.25);
}
.ds-kicker {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 10px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: #f2b63c;
  margin-bottom: 12px;
}
.ds-card-title {
  font-family: 'Bricolage Grotesque', sans-serif;
  font-weight: 700;
  font-size: 1.5rem;
  line-height: 1.2;
  letter-spacing: -0.02em;
  color: #f1efe8;
  margin-bottom: 12px;
}
.ds-card-desc {
  font-family: 'Hanken Grotesk', system-ui, sans-serif;
  font-size: 0.875rem;
  line-height: 1.5;
  color: #8f939e;
  margin-bottom: 20px;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.ds-autocomplete {
  background: #14171d;
  border: 1px solid rgba(241,239,232,0.24);
  border-radius: 8px;
  box-shadow: 0 24px 64px rgba(0,0,0,0.55);
  padding: 6px;
  max-height: 300px;
  overflow-y: auto;
  list-style: none;
  margin: 0;
}
.ds-autocomplete-item {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 16px;
  align-items: center;
  padding: 10px 14px;
  border-radius: 4px;
  cursor: pointer;
  transition: background-color 0.1s;
  font-family: 'Hanken Grotesk', system-ui, sans-serif;
  font-size: 15px;
  font-weight: 500;
  color: #f1efe8;
}
.ds-autocomplete-item:hover,
.ds-autocomplete-item--active {
  background: #1b1f27;
}
.ds-autocomplete-meta {
  font-family: 'IBM Plex Mono', monospace;
  font-size: 11px;
  color: #8f939e;
  white-space: nowrap;
}

.ds-theme-toggle {
  width: 36px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 9999px;
  border: 1px solid rgba(241,239,232,0.09);
  background: transparent;
  color: #8f939e;
  cursor: pointer;
  transition: color 0.15s, border-color 0.15s;
}
.ds-theme-toggle:hover {
  color: #f1efe8;
  border-color: rgba(241,239,232,0.24);
}
.ds-theme-toggle:focus-visible {
  outline: 2px solid #ff5c4d;
  outline-offset: 2px;
}
[data-theme="dark"] .ds-theme-icon--moon { display: none; }
[data-theme="light"] .ds-theme-icon--sun { display: none; }

.ds-bullseye {
  width: 10px;
  height: 10px;
  border-radius: 9999px;
  background: #ff5c4d;
  box-shadow: 0 0 0 3px #0d0f13, 0 0 0 4.5px #ff5c4d;
  flex-shrink: 0;
}
.ds-bullseye:focus-visible {
  outline: 2px solid #ff5c4d;
  outline-offset: 4px;
}
